import { StepFrame, useSteps } from '../../viz/stepper';
import { Svg, T, tok } from '../../viz/svg';
import m from '../../../../../engine/ts/packages/bench/results/matrix-2026-10-31.json';

// Chapter 285: the three sections of the benchmark matrix, every number
// read from engine/ts/packages/bench/results/matrix-2026-10-31.json
// (generated by engine/ts/packages/bench/src/matrix.ts). Nothing is typed
// in by hand. e2e figures are best of 9 fresh processes; see the JSON's
// meta for the machine, versions and noise.
type Side = { originalMs: { best: number }; viscosityMs: { best: number }; speedupBest: number };
type E2E = { program: string; node: Side; bun: Side };
const rows = m.e2e.rows as E2E[];
const sum = m.e2e.summary;
const cli = m.compileSpeed.cli;
const inproc = m.compileSpeed.inProcess;
const drip = m.drip.geomean;

const heat = rows.find((r) => r.program === 'heat') as E2E;
const x2 = (v: number) => `${v}×`;

type Kind = 'node' | 'bun' | 'orig' | 'compile' | 'drip';
const STATES: { k: Kind; note: string }[] = [
  { k: 'node', note: `Node 22 (V8): how many times faster each program runs after Viscosity, best of ${m.meta.settings.e2eRuns} fresh processes. Every program gains; the geometric mean is ${x2(sum.node.geomeanSpeedupBest)}.` },
  { k: 'bun', note: `The same programs and the same compiled code on Bun ${m.meta.versions.bun} (JavaScriptCore). The mean drops to ${x2(sum.bun.geomeanSpeedupBest)}, and heat goes from ${x2(heat.node.speedupBest)} to ${x2(heat.bun.speedupBest)}: no gain beyond the noise.` },
  { k: 'orig', note: `Why: the originals. Bun runs the unchanged programs ${x2(sum.bunVsNode.originalGeomean)} faster than Node (geomean), the compiled ones only ${x2(sum.bunVsNode.viscosityGeomean)} faster. Heat’s original takes ${heat.node.originalMs.best} ms on Node and ${heat.bun.originalMs.best} ms on Bun; compiled, ${heat.node.viscosityMs.best} and ${heat.bun.viscosityMs.best}.` },
  { k: 'compile', note: `The compiler itself, over ${m.compileSpeed.programs} corpus programs. As command-line tools, one process per file, Rust is ${x2(cli.totalSpeedup)} faster, much of it Node’s start-up. Inside one Node process, the Rust engine as WebAssembly is ${x2(inproc.totalSpeedup)} faster than the TypeScript engine, an upper bound (see the note in the text).` },
  { k: 'drip', note: `Drip, from the committed results of Part XII: the TS VM against the tree-walker, drip-rs against the TS VM, and drip-rs against the tree-walker, as geometric means over the timed programs.` },
];

const L = 70;
const W = 400 - L - 40;

function SpeedBars({ which, both }: { which: 'node' | 'bun'; both: boolean }) {
  const max = 5;
  const x = (v: number) => L + (v / max) * W;
  const rowH = 32;
  const top = 26;
  const all = [...rows, { program: 'geomean', node: { speedupBest: sum.node.geomeanSpeedupBest }, bun: { speedupBest: sum.bun.geomeanSpeedupBest } }];
  return (
    <g>
      <rect x={L} y={6} width={10} height={10} rx={2} fill={tok('brand')} />
      <T x={L + 14} y={11} size={10}>Node (V8)</T>
      {both && (
        <g>
          <rect x={L + 90} y={6} width={10} height={10} rx={2} fill={tok('accent')} />
          <T x={L + 104} y={11} size={10}>Bun (JSC)</T>
        </g>
      )}
      {[1, 2, 3, 4, 5].map((v) => (
        <g key={v}>
          <line x1={x(v)} x2={x(v)} y1={top - 4} y2={top + all.length * rowH} stroke={tok(v === 1 ? 'ink' : 'line', v === 1 ? 0.6 : 1)} strokeDasharray="3 3" />
          <T x={x(v)} y={top + all.length * rowH + 8} size={9} anchor="middle" fill={tok('muted')}>{`${v}×`}</T>
        </g>
      ))}
      {all.map((r, i) => {
        const y = top + i * rowH;
        const n = r.node.speedupBest;
        const b = r.bun.speedupBest;
        const hot = r.program === 'heat' && both;
        return (
          <g key={r.program}>
            <T x={L - 6} y={y + 12} size={10} mono anchor="end" weight={r.program === 'geomean' ? 700 : undefined} fill={hot ? tok('danger') : undefined}>{r.program}</T>
            <rect x={L} y={y + 2} width={x(n) - L} height={both ? 10 : 18} rx={2} fill={tok('brand', which === 'bun' ? 0.45 : 1)} />
            <T x={x(n) + 4} y={y + (both ? 7 : 11)} size={9} mono>{x2(n)}</T>
            {both && (
              <g>
                <rect x={L} y={y + 14} width={x(b) - L} height={10} rx={2} fill={tok('accent')} />
                <T x={x(b) + 4} y={y + 19} size={9} mono fill={hot ? tok('danger') : undefined}>{x2(b)}</T>
              </g>
            )}
          </g>
        );
      })}
    </g>
  );
}

function Originals() {
  const max = Math.max(...rows.flatMap((r) => [r.node.originalMs.best, r.bun.originalMs.best]));
  const x = (v: number) => L + (v / max) * (W - 20);
  const rowH = 38;
  const top = 26;
  const bars: [string, (r: E2E) => number, string][] = [
    ['Node original', (r) => r.node.originalMs.best, 'brand'],
    ['Bun original', (r) => r.bun.originalMs.best, 'accent'],
    ['Node compiled', (r) => r.node.viscosityMs.best, 'f2'],
    ['Bun compiled', (r) => r.bun.viscosityMs.best, 'f4'],
  ];
  return (
    <g>
      {bars.map(([l, , c], k) => (
        <g key={l}>
          <rect x={8 + k * 98} y={6} width={10} height={10} rx={2} fill={tok(c)} />
          <T x={22 + k * 98} y={11} size={9}>{l}</T>
        </g>
      ))}
      {rows.map((r, i) => {
        const y = top + i * rowH;
        return (
          <g key={r.program}>
            <T x={L - 6} y={y + 16} size={10} mono anchor="end" fill={r === heat ? tok('danger') : undefined}>{r.program}</T>
            {bars.map(([l, f, c], k) => (
              <g key={l}>
                <rect x={L} y={y + 2 + k * 8} width={Math.max(1, x(f(r)) - L)} height={7} rx={1.5} fill={tok(c)} />
                {r === heat && <T x={x(f(r)) + 4} y={y + 6 + k * 8} size={8} mono>{`${f(r)} ms`}</T>}
              </g>
            ))}
          </g>
        );
      })}
      <T x={L} y={top + rows.length * rowH + 6} size={9} fill={tok('muted')}>milliseconds of each program’s timed section, best of 9</T>
    </g>
  );
}

function Compile() {
  const pairs: { label: string; ts: number; rs: number; unit: string; rsLabel: string; k: number }[] = [
    { label: 'CLI, one process per file', ts: cli.totalMedianMs.ts, rs: cli.totalMedianMs.rust, unit: 'ms', rsLabel: 'Rust CLI', k: cli.totalSpeedup },
    { label: 'in one Node process', ts: inproc.totalMedianUs.ts, rs: inproc.totalMedianUs.wasm, unit: 'µs', rsLabel: 'Rust as wasm', k: inproc.totalSpeedup },
  ];
  return (
    <g>
      <T x={8} y={11} size={11} weight={700} fill={tok('brand')}>{`Compiling ${m.compileSpeed.programs} programs: sum of medians`}</T>
      {pairs.map((p, i) => {
        const y = 40 + i * 100;
        const x = (v: number) => 110 + (v / p.ts) * 240;
        return (
          <g key={p.label}>
            <T x={8} y={y} size={11} weight={700}>{p.label}</T>
            <T x={104} y={y + 22} size={10} anchor="end">TypeScript</T>
            <rect x={110} y={y + 14} width={x(p.ts) - 110} height={16} rx={2} fill={tok('muted')} />
            <T x={x(p.ts) - 4} y={y + 22} size={9} mono anchor="end" fill={tok('paper')}>{`${p.ts} ${p.unit}`}</T>
            <T x={104} y={y + 46} size={10} anchor="end">{p.rsLabel}</T>
            <rect x={110} y={y + 38} width={Math.max(2, x(p.rs) - 110)} height={16} rx={2} fill={tok('brand')} />
            <T x={x(p.rs) + 4} y={y + 46} size={9} mono>{`${p.rs} ${p.unit}`}</T>
            <T x={360} y={y + 70} size={11} mono anchor="end" weight={700} fill={tok('brand')}>{`${p.k}× faster`}</T>
          </g>
        );
      })}
    </g>
  );
}

function Drip() {
  const items: [string, number][] = [
    ['TS VM vs tree-walker', drip.vmVsTree],
    ['drip-rs vs TS VM', drip.rustVsVm],
    ['drip-rs vs tree-walker', drip.rustVsTree],
  ];
  const x = (v: number) => 150 + (v / 10) * 210;
  return (
    <g>
      <T x={8} y={11} size={11} weight={700} fill={tok('brand')}>Drip: geometric mean speed-up</T>
      {items.map(([l, v], i) => {
        const y = 44 + i * 56;
        return (
          <g key={l}>
            <T x={144} y={y + 9} size={10} anchor="end">{l}</T>
            <rect x={150} y={y} width={x(v) - 150} height={18} rx={2} fill={tok(i === 0 ? 'accent' : 'brand', i === 2 ? 1 : 0.7)} />
            <T x={x(v) + 4} y={y + 9} size={10} mono weight={700}>{x2(v)}</T>
          </g>
        );
      })}
      <T x={8} y={222} size={9} fill={tok('muted')}>string_equality fails on both VMs; zoo_batch runs for a fixed time.</T>
    </g>
  );
}

export default function MatrixSteps() {
  const s = useSteps(STATES);
  const st = s.state;
  return (
    <StepFrame title="The benchmark matrix, 2026-10-31" steps={s} note={st.note}>
      <Svg w={400} h={240} title="End-to-end speed-ups on Node and Bun, original run times, compile speed of the two engines, and Drip's three implementations">
        {st.k === 'node' && <SpeedBars which="node" both={false} />}
        {st.k === 'bun' && <SpeedBars which="bun" both />}
        {st.k === 'orig' && <Originals />}
        {st.k === 'compile' && <Compile />}
        {st.k === 'drip' && <Drip />}
      </Svg>
    </StepFrame>
  );
}
